import { useRef, type HTMLAttributes, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { Collapsible, CollapsiblePanel, CollapsibleTrigger } from '../../ui/collapsible';
import { SkipLink } from '../../ui/visually-hidden';
import { docsLayoutVariants } from './docs-layout.variants';
import { useI18n } from '../../i18n/I18nProvider';
import { Outline, type OutlineItem } from './Outline';

export interface DocsLayoutProps extends Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'children'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** The article (headings with ids matching `toc`). */
  children?: ReactNode;
  /** Top bar (logo, search, version switcher, theme, MobileNav trigger). */
  header?: ReactNode;
  /** Left navigation — usually a NavList (it provides its own `<nav>` landmark). Hidden below `lg`. */
  nav?: ReactNode;
  /** Table of contents entries; renders the Outline (scroll-spy) on the right and a Collapsible copy below `lg`. */
  toc?: OutlineItem[];
  /** Heading / accessible name of the table of contents. */
  tocLabel?: string;
  /** Replaces the right column (when not using `toc`). */
  aside?: ReactNode;
  /**
   * Inside an app shell that already owns <main> and the skip link (SidebarLayout, StackedLayout):
   * render the content region as a plain <div> and drop this layout's skip link.
   */
  embedded?: boolean;
  /** After the article (previous / next links, feedback, last updated). */
  footer?: ReactNode;
  mainId?: string;
  skipLinkLabel?: string;
  fullScreen?: boolean;
}

/**
 * Documentation shell: top bar · left nav · article · right table of contents with scroll-spy
 * (Outline). The article column scrolls on its own and is the Outline's scroll root. Below `lg`
 * the nav hides and the table of contents moves into a Collapsible above the article.
 */
export function DocsLayout({
  children,
  header,
  nav,
  toc,
  tocLabel: tocLabelProp,
  aside,
  footer,
  embedded = false,
  mainId = 'main',
  skipLinkLabel: skipLinkLabelProp,
  fullScreen = false,
  className,
  ...props
}: DocsLayoutProps) {
  const { t } = useI18n();
  const tocLabel = tocLabelProp ?? t('nav.onThisPage');
  const skipLinkLabel = skipLinkLabelProp ?? t('skip.content');
  const MainTag = embedded ? 'div' : 'main';
  const mainRef = useRef<HTMLDivElement>(null);
  const s = docsLayoutVariants({ fullScreen });
  const hasToc = toc != null && toc.length > 0;
  return (
    <div className={cn(s.root(), className)} {...props}>
      {!embedded && (
        <SkipLink targetId={mainId} className={s.skipLink()}>
          {skipLinkLabel}
        </SkipLink>
      )}
      {header != null && <header className={s.header()}>{header}</header>}
      <div className={s.body()}>
        {nav != null && <div className={s.nav()}>{nav}</div>}
        <MainTag ref={mainRef} id={mainId} tabIndex={-1} className={s.main()}>
          <div className={s.column()}>
            {hasToc && (
              <Collapsible variant="row" className={s.mobileToc()}>
                <CollapsibleTrigger>{tocLabel}</CollapsibleTrigger>
                <CollapsiblePanel>
                  <Outline items={toc} label={tocLabel} landmark={false} hideHeading scrollRootRef={mainRef} />
                </CollapsiblePanel>
              </Collapsible>
            )}
            <article className={s.article()}>{children}</article>
            {footer != null && <div className={s.footer()}>{footer}</div>}
          </div>
        </MainTag>
        {(hasToc || aside != null) && (
          <div className={s.toc()}>{aside ?? (hasToc && <Outline items={toc} label={tocLabel} scrollRootRef={mainRef} />)}</div>
        )}
      </div>
    </div>
  );
}

import { useEffect, useEffectEvent, useId, useState, type HTMLAttributes, type MouseEvent, type ReactNode, type Ref, type RefObject } from 'react';
import { cn } from '../../utils/cn';
import { useI18n } from '../../i18n/I18nProvider';
import { outlineVariants } from './docs-layout.variants';

export interface OutlineItem {
  /** `id` of the heading in the article. */
  id: string;
  label: ReactNode;
  /** Heading depth: 2 (section) or 3 (sub-section, indented). */
  level?: 2 | 3;
}

export interface OutlineProps extends Omit<HTMLAttributes<HTMLElement>, 'className' | 'children'> {
  className?: string;
  ref?: Ref<HTMLElement>;
  items: OutlineItem[];
  /** Heading and accessible name. */
  label?: string;
  /** Hide the visible heading (e.g. inside a Collapsible whose trigger already says it). */
  hideHeading?: boolean;
  /** Render as a `<nav>` landmark (default) or a plain `<div>` (when nested in another named region). */
  landmark?: boolean;
  /** Current section (controlled). Without it, scroll-spy tracks the heading in view. */
  activeId?: string;
  onActiveChange?: (id: string) => void;
  /** Scroll container the headings move in (the layout's main column). Defaults to the viewport. */
  scrollRootRef?: RefObject<Element | null>;
  /** Called after a link moved focus to its heading. */
  onNavigate?: (id: string) => void;
}

const NATIVELY_FOCUSABLE = 'a[href], button, input, select, textarea, summary, [tabindex]';

/**
 * Table of contents with scroll-spy: the link of the heading in view gets aria-current="location".
 * Activating a link moves focus (not just scroll) to the heading. IntersectionObserver is optional:
 * without it (jsdom, old browsers) the active item only follows clicks.
 */
export function Outline({
  items,
  label: labelProp,
  hideHeading = false,
  landmark = true,
  activeId: activeProp,
  onActiveChange,
  scrollRootRef,
  onNavigate,
  className,
  ref,
  ...props
}: OutlineProps) {
  const { t } = useI18n();
  const label = labelProp ?? t('nav.onThisPage');
  const [inner, setInner] = useState<string | undefined>(items[0]?.id);
  const active = activeProp ?? inner;
  const headingId = useId();
  const s = outlineVariants();
  const ids = items.map((i) => i.id).join('|');
  const spy = useEffectEvent((id: string) => {
    setInner(id);
    onActiveChange?.(id);
  });

  useEffect(() => {
    if (typeof IntersectionObserver === 'undefined') return;
    const targets = ids
      .split('|')
      .map((id) => document.getElementById(id))
      .filter((el): el is HTMLElement => el !== null);
    if (!targets.length) return;
    const visible = new Set<string>();
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) visible.add(entry.target.id);
          else visible.delete(entry.target.id);
        }
        const first = targets.find((t) => visible.has(t.id));
        if (first) spy(first.id);
      },
      { root: scrollRootRef?.current ?? null, rootMargin: '0px 0px -65% 0px', threshold: 0 },
    );
    targets.forEach((t) => observer.observe(t));
    return () => observer.disconnect();
  }, [ids, scrollRootRef]);

  function go(event: MouseEvent<HTMLAnchorElement>, id: string) {
    const target = document.getElementById(id);
    if (!target) return;
    event.preventDefault();
    if (!target.matches(NATIVELY_FOCUSABLE)) target.setAttribute('tabindex', '-1');
    target.focus({ preventScroll: true });
    const reduce = typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    target.scrollIntoView?.({ block: 'start', behavior: reduce ? 'auto' : 'smooth' });
    setInner(id);
    onActiveChange?.(id);
    onNavigate?.(id);
    try {
      history.replaceState(history.state, '', `#${id}`);
    } catch {}
  }

  const list = (
    <ul className={s.list()}>
      {items.map((item) => (
        <li key={item.id}>
          <a
            href={`#${item.id}`}
            aria-current={item.id === active ? 'location' : undefined}
            className={outlineVariants({ level: item.level ?? 2 }).link()}
            onClick={(e) => go(e, item.id)}
          >
            {item.label}
          </a>
        </li>
      ))}
    </ul>
  );

  const heading = !hideHeading && (
    <p id={headingId} className={s.heading()}>
      {label}
    </p>
  );
  if (!landmark) {
    return (
      <div ref={ref as Ref<HTMLDivElement> | undefined} className={cn(s.root(), className)} {...props}>
        {heading}
        {list}
      </div>
    );
  }
  return (
    <nav
      ref={ref}
      aria-labelledby={hideHeading ? undefined : headingId}
      aria-label={hideHeading ? label : undefined}
      className={cn(s.root(), className)}
      {...props}
    >
      {heading}
      {list}
    </nav>
  );
}

import { tv, type VariantProps } from '../../utils/tv';

export const docsLayoutVariants = tv({
  slots: {
    root: 'relative flex flex-col overflow-hidden bg-background font-sans text-foreground',
    skipLink: 'focus:absolute',
    header: 'flex h-12 shrink-0 items-center gap-3 border-b border-border bg-chrome px-4',
    body: 'flex min-h-0 flex-1',
    nav: 'hidden w-60 shrink-0 overflow-y-auto border-e border-border px-3 py-6 lg:block',
    main: 'min-w-0 flex-1 overflow-y-auto outline-none',
    column: 'mx-auto w-full max-w-3xl px-4 py-8 sm:px-8',
    mobileToc: 'mb-6 rounded-lg border border-border bg-card px-3 lg:hidden',
    article: 'min-w-0',
    footer: 'mt-12 border-t border-border pt-6',
    toc: 'hidden w-56 shrink-0 overflow-y-auto py-8 pe-4 ps-2 lg:block',
  },
  variants: {
    fullScreen: {
      true: { root: 'h-dvh' },
      false: { root: 'h-full min-h-full' },
    },
  },
  defaultVariants: { fullScreen: false },
});

export const outlineVariants = tv({
  slots: {
    root: 'flex flex-col gap-2',
    heading: 'px-2 font-mono text-[10.5px] font-semibold tracking-[0.14em] text-muted-foreground uppercase',
    list: 'm-0 flex list-none flex-col border-s border-border p-0',
    link: [
      '-ms-px block border-s-2 border-transparent py-1 pe-2 text-[12.5px] leading-snug text-muted-foreground',
      'transition-colors hover:text-foreground motion-reduce:transition-none',
      'aria-[current=location]:border-primary aria-[current=location]:font-medium aria-[current=location]:text-primary-text',
      'rounded-e-sm focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
    ],
  },
  variants: {
    level: {
      2: { link: 'ps-3' },
      3: { link: 'ps-6' },
    },
  },
  defaultVariants: { level: 2 },
});

export type DocsLayoutVariantProps = VariantProps<typeof docsLayoutVariants>;
export type OutlineVariantProps = VariantProps<typeof outlineVariants>;

export { DocsLayout, type DocsLayoutProps } from './DocsLayout';
export { Outline, type OutlineProps, type OutlineItem } from './Outline';
export { docsLayoutVariants, outlineVariants, type DocsLayoutVariantProps, type OutlineVariantProps } from './docs-layout.variants';
export { doc as docsLayoutDoc } from './DocsLayout.doc';

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'DocsLayout',
  group: 'Layout',
  status: 'beta',
  description:
    'Documentation shell: top bar · left nav (a NavList) · article · right table of contents. The `Outline` sub-component is the table of contents: scroll-spy with IntersectionObserver (rooted in the article column, guarded where it is missing) marks the heading in view with aria-current="location", and activating a link moves focus to the heading. Below `lg` the nav hides and the table of contents moves into a Collapsible above the article. Fills its container; `fullScreen` switches to `h-dvh`.',
  primitive: '@base-ui/react/collapsible (small-screen table of contents)',
  pattern: 'landmarks (header, nav, main, "On this page" nav) + disclosure',
  keyboard: [
    ['Tab', 'Skip link, top bar, left nav, the article, then the table of contents links'],
    ['Enter on a table of contents link', 'Scrolls to the heading and moves focus to it'],
    ['Enter / Space on "On this page"', 'Small screens: expands or collapses the table of contents'],
  ],
  tokens: ['background', 'foreground', 'chrome', 'card', 'border', 'primary', 'primary-text', 'muted-foreground', 'focus-ring'],
};
